INSERT IGNORE INTO `team_members` (`id`, `name`, `role`, `email`, `photo_url`, `bio`, `facts`, `sort_order`, `is_visible`, `updated_by`, `updated_at`, `created_at`) VALUES (1,'Maria Vergara','Founder & CEO','maria.vergara@casavergararesort.com','https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=900&q=80','Maria founded Casa Vergara in 2021 with a simple belief: guests should feel at home the moment they arrive. She still greets arrivals personally most weekends.','15+ years in hospitality leadership\nDrives our sustainability program\nHospitality Excellence awardee, 2023',1,1,NULL,'2026-10-16 11:02:08','2026-10-16 11:02:08');
INSERT IGNORE INTO `team_members` (`id`, `name`, `role`, `email`, `photo_url`, `bio`, `facts`, `sort_order`, `is_visible`, `updated_by`, `updated_at`, `created_at`) VALUES (2,'Carlos Rodriguez','General Manager','carlos.rodriguez@casavergararesort.com','https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&w=900&q=80','Carlos keeps every corner of the resort running smoothly, from housekeeping standards to large event turnovers, without ever losing the warm welcome.','Oversees daily resort operations\nLeads a team of 120+ staff\nCertified Hotel Administrator',2,1,NULL,'2026-10-16 11:02:08','2026-10-16 11:02:08');
INSERT IGNORE INTO `team_members` (`id`, `name`, `role`, `email`, `photo_url`, `bio`, `facts`, `sort_order`, `is_visible`, `updated_by`, `updated_at`, `created_at`) VALUES (3,'Isabella Santos','Guest Relations','isabella.santos@casavergararesort.com','https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=900&q=80','Isabella is the person behind the little touches: the anniversary cake, the early check-in, the room with the better sunset view.','Handles VIP and event guests\nSpeaks English, Filipino and Spanish\n98% guest satisfaction rating',3,1,NULL,'2026-10-16 11:02:08','2026-10-16 11:02:08');
INSERT IGNORE INTO `team_members` (`id`, `name`, `role`, `email`, `photo_url`, `bio`, `facts`, `sort_order`, `is_visible`, `updated_by`, `updated_at`, `created_at`) VALUES (4,'David Chen','Executive Chef','david.chen@casavergararesort.com','https://images.unsplash.com/photo-1566492031773-4f4e44671857?auto=format&fit=crop&w=900&q=80','David builds our menus around what local farmers and fishers bring in that morning, blending Filipino flavors with modern technique.','Leads all resort dining outlets\nFarm-to-table sourcing advocate\nTrained in Singapore and Manila',4,1,NULL,'2026-10-16 11:02:08','2026-10-16 11:02:08');
INSERT IGNORE INTO `terms_and_conditions` (`id`, `booking_type`, `version`, `content`, `is_active`, `created_at`) VALUES (1,'room','1.1','## Quotation & Confirmation\nA valid quotation must be reviewed and approved by the client before any room reservation is considered confirmed. Reservation dates are held tentatively while a quotation is pending your approval.\n\n## Downpayment\nA downpayment of at least 50% of the quoted amount is required to secure the reservation. Reservations without a validated downpayment may be released to other guests.\n\n## Cancellations & Refunds\nCancellations made 7 days or more before the reservation date are eligible for a 50% refund of the downpayment. Cancellations made less than 7 days before the reservation date forfeit the downpayment in full.\n\n## Check-in & Check-out\nCheck-in and check-out times will be specified in your confirmed quotation. Early check-in or late check-out requests are subject to availability and may incur additional charges.',0,'2026-10-16 11:02:08');
INSERT IGNORE INTO `terms_and_conditions` (`id`, `booking_type`, `version`, `content`, `is_active`, `created_at`) VALUES (2,'event','1.0','## Quotation & Customization\nAll event customizations (theme, motif, lights, sound, and add-ons) are subject to a formal quotation and must be approved by the client before the booking is confirmed. Prices shown during customization are estimates until the quotation is issued.\n\n## Downpayment\nA downpayment of at least 50% of the quoted amount is required to reserve your event date. The date is not guaranteed until this downpayment is verified.\n\n## Final Details\nFinal guest count and customization details must be confirmed at least 5 days before the event date. Changes requested after this window may not be guaranteed and may affect pricing.\n\n## Cancellations & Refunds\nCancellations made 14 days or more before the event date are eligible for a 50% refund of the downpayment. Cancellations made less than 14 days before the event forfeit the downpayment in full.\n\n## Force Majeure\nCasa Vergara is not liable for delays or disruptions caused by circumstances beyond its reasonable control, including severe weather, government advisories, or other force majeure events.\n\n## Outside Vendors\nOutside catering, decor, or entertainment services require prior written approval from Casa Vergara management before the event date.',0,'2026-10-16 11:02:08');
INSERT IGNORE INTO `terms_and_conditions` (`id`, `booking_type`, `version`, `content`, `is_active`, `created_at`) VALUES (3,'privacy','1.0','## Information We Collect\nWhen you create an account, make a reservation, or request an event quotation, we collect information such as your name, email address, phone number, and the booking details you provide (dates, guest count, customization preferences, and uploaded proof of payment).\n\n## How We Use Your Information\nWe use your information to process reservations and quotations, verify payments, send booking confirmations and updates by email, respond to inquiries, and improve our services. We do not sell your personal information to third parties.\n\n## Payment Proof & Uploaded Files\nProof-of-payment files you upload are stored securely and are only accessible to authorized Casa Vergara staff for the purpose of validating your payment. Please avoid uploading documents containing sensitive information beyond what is needed to confirm payment.\n\n## Data Retention\nWe retain booking and account records for as long as reasonably necessary to fulfill the purposes described in this policy, meet legal obligations, and resolve disputes.\n\n## Your Choices\nYou may request access to, correction of, or deletion of your personal information by contacting us directly. Deleting your account may affect our ability to honor existing reservations.\n\n## Contact Us\nIf you have questions about this Privacy Policy or how your data is handled, please reach out through the Contact page or the details in our footer.',0,'2026-10-16 11:02:08');
INSERT IGNORE INTO `terms_and_conditions` (`id`, `booking_type`, `version`, `content`, `is_active`, `created_at`) VALUES (4,'room','1.1','## Quotation & Confirmation\nA valid quotation must be reviewed and approved by the client before any room reservation is considered confirmed. Reservation dates are held tentatively while a quotation is pending your approval.\n\n## Downpayment\nA downpayment of at least 50% of the quoted amount is required to secure the reservation. Reservations without a validated downpayment may be released to other guests.\n\n## Cancellations & Refunds\nCancellations made 7 days or more before the reservation date are eligible for a 50% refund of the downpayment. Cancellations made less than 7 days before the reservation date forfeit the downpayment in full.\n\n## Check-in & Check-out\nCheck-in and check-out times will be specified in your confirmed quotation. Early check-in or late check-out requests are subject to availability and may incur additional charges.\n\n## Identification\nCasa Vergara reserves the right to request valid government-issued identification upon check-in for all room bookings.',0,'2026-10-16 11:02:08');
